// =======================================================================
// Set this to YOUR IANA timezone (e.g. "America/New_York", "Europe/London").
// 'This week' = Mon–Fri of the current calendar week in this timezone.
// =======================================================================
const TZ = "America/New_York";

// ----- helpers -----
const ymdInTZ = (d) => {
  const parts = new Intl.DateTimeFormat("en-CA", {
    timeZone: TZ, year: "numeric", month: "2-digit", day: "2-digit"
  }).formatToParts(d);
  const o = {};
  for (const p of parts) o[p.type] = p.value;
  return `${o.year}-${o.month}-${o.day}`;
};
const dowOf = (ymd) => {
  const [y, m, d] = ymd.split("-").map(Number);
  return new Date(Date.UTC(y, m - 1, d)).getUTCDay(); // 0=Sun..6=Sat
};
const prevWeekday = (ymd) => {
  const [y, m, d] = ymd.split("-").map(Number);
  const dt = new Date(Date.UTC(y, m - 1, d));
  do { dt.setUTCDate(dt.getUTCDate() - 1); }
  while (dt.getUTCDay() === 0 || dt.getUTCDay() === 6);
  return dt.toISOString().slice(0, 10);
};
const mondayOf = (ymd) => {
  const [y, m, d] = ymd.split("-").map(Number);
  const dt = new Date(Date.UTC(y, m - 1, d));
  const dow = dt.getUTCDay();
  const shift = (dow === 0 ? -6 : 1 - dow);
  dt.setUTCDate(dt.getUTCDate() + shift);
  return dt.toISOString().slice(0, 10);
};

// ----- normalise Notion rows -----
const num = (p, k) => {
  const v = p[k];
  return (typeof v === "number" && !isNaN(v)) ? v : 0;
};
const rows = $input.all().map(it => {
  const p = it.json || {};
  let dateRaw = p["Date"];
  if (dateRaw && typeof dateRaw === "object") dateRaw = dateRaw.start;
  if (!dateRaw) return null;
  return {
    date: String(dateRaw).slice(0, 10),
    callsConverted: num(p, "Calls Converted"),
    gpCalls: num(p, "GP Call (only final)"),
    callsClosed: num(p, "Calls Closed"),
    contractValue: num(p, "Contract Value"),
    cashCollected: num(p, "Cash Collected"),
  };
}).filter(Boolean);

// Dedupe by date (last wins)
const byDate = new Map();
for (const r of rows) byDate.set(r.date, r);

// Weekdays only, ascending
const weekdays = [...byDate.values()]
  .filter(r => { const w = dowOf(r.date); return w >= 1 && w <= 5; })
  .sort((a, b) => a.date.localeCompare(b.date));
const wMap = new Map(weekdays.map(r => [r.date, r]));

// ----- 1) Streak: consecutive weekdays with Calls Converted >= 2 -----
// Current: walk back from most recent recorded weekday
let currentStreak = 0;
if (weekdays.length) {
  let cursor = weekdays[weekdays.length - 1].date;
  while (true) {
    const r = wMap.get(cursor);
    if (!r || r.callsConverted < 2) break;
    currentStreak++;
    cursor = prevWeekday(cursor);
  }
}
// Record: scan history, track longest run of consecutive weekdays each >=2
let bestStreak = 0, runLen = 0, bestEndedOn = null;
for (let i = 0; i < weekdays.length; i++) {
  const r = weekdays[i];
  const consecutive = i === 0 ? true : (weekdays[i - 1].date === prevWeekday(r.date));
  if (r.callsConverted >= 2 && consecutive) runLen++;
  else if (r.callsConverted >= 2) runLen = 1;
  else {
    if (runLen > bestStreak) { bestStreak = runLen; bestEndedOn = weekdays[i - 1]?.date || null; }
    runLen = 0;
  }
}
if (runLen > bestStreak) {
  bestStreak = runLen;
  bestEndedOn = weekdays[weekdays.length - 1]?.date || null;
}

// ----- 2 & 3) This week's top CV and CC, plus all-time records -----
const today = ymdInTZ(new Date());
const weekStart = mondayOf(today);
const [wy, wm, wd] = weekStart.split("-").map(Number);
const friDt = new Date(Date.UTC(wy, wm - 1, wd));
friDt.setUTCDate(friDt.getUTCDate() + 4);
const weekEnd = friDt.toISOString().slice(0, 10);

const thisWeek = weekdays.filter(r => r.date >= weekStart && r.date <= weekEnd);
const topCV = thisWeek.reduce((m, r) => Math.max(m, r.contractValue), 0);
const topCC = thisWeek.reduce((m, r) => Math.max(m, r.cashCollected), 0);

let recCV = 0, recCVDate = null, recCC = 0, recCCDate = null;
for (const r of weekdays) {
  if (r.contractValue > recCV) { recCV = r.contractValue; recCVDate = r.date; }
  if (r.cashCollected > recCC) { recCC = r.cashCollected; recCCDate = r.date; }
}

// ----- 4) Close rate this week + best historical week -----
const closes = thisWeek.reduce((s, r) => s + r.callsClosed, 0);
const gps = thisWeek.reduce((s, r) => s + r.gpCalls, 0);
const rateNow = gps > 0 ? closes / gps : null;

const weekly = new Map();
for (const r of weekdays) {
  const mon = mondayOf(r.date);
  const agg = weekly.get(mon) || { closes: 0, gp: 0 };
  agg.closes += r.callsClosed;
  agg.gp += r.gpCalls;
  weekly.set(mon, agg);
}
let bestRate = null, bestRateWeek = null;
for (const [mon, agg] of weekly.entries()) {
  if (agg.gp < 1) continue;
  const rate = agg.closes / agg.gp;
  if (bestRate === null || rate > bestRate) { bestRate = rate; bestRateWeek = mon; }
}

return [{
  json: {
    generatedAt: new Date().toISOString(),
    metrics: {
      streak: {
        current: currentStreak,
        record: bestStreak,
        recordEndedOn: bestEndedOn
      },
      contractValueWeek: {
        current: topCV,
        record: recCV,
        recordDate: recCVDate
      },
      cashCollectedWeek: {
        current: topCC,
        record: recCC,
        recordDate: recCCDate
      },
      closeRateWeek: {
        current: rateNow,
        currentCloses: closes,
        currentGpCalls: gps,
        record: bestRate,
        recordWeekStart: bestRateWeek
      }
    }
  }
}];
